# -*- coding: utf-8 -*-
"""Lesson content (own wording). Every rule cites a recorded source and carries
check substrings that tools/lessons.py verifies against the source text:
  TR:n  Traffic Regulations 1961 section n (Wikisource, pinned revision)
  TO:n  Traffic Ordinance section n (Wikisource, pinned revision)
  LT:n  sign n in the Ministry of Transport signs table (לות"ם, Sept 2022)
  LTP:n part n heading of that table
  Q:id  official theory question bank item id (data.gov.il, CC BY)
A label after the key, e.g. 'TR:64(א)(1)', is the sub-section shown to the user."""

def R(text, src, *checks, also=(), q=(), qp=()):
    # q / qp: bank questions this rule was written to teach fully / in part (read by tools/coverage.py)
    return {'t': text, 's': src, 'chk': list(checks), 'also': list(also), **({'q': list(q)} if q else {}), **({'qp': list(qp)} if qp else {})}

def C(front, back, src, *checks):
    return {'f': front, 'b': back, 's': src, **({'chk': list(checks)} if checks else {})}

def X(qid, text, src, *checks, also=()):
    # also: extra (source, checks) pairs, verified like rule 'also' sources (v1.11)
    return {'q': qid, 't': text, 's': src, 'chk': list(checks), **({'also': list(also)} if also else {})}

