   R('"מאיט" (Retarder) – מנגנון האטה חשמלי או הידראולי במערכת ההנעה, שמאט את הרכב בלי מערכת הבלמים.', 'TR:324', '”מאיט“ (Retarder) – מנגנון האטה חשמלי או הידראולי', 'בלא שהוא קשור למערכת הבלמים של הרכב', also=[('TR:330', ['10,000 ק״ג או יותר ואשר שנת ייצורו 1987 או לאחריה, יותקן מאיט', 'מנוע דיזל ושמשקלו הכולל המותר 6,000 ק״ג או יותר יותקן בלמנוע'])]),
   R('הוצב תמרור המזהיר על ירידה מסוכנת? נוהגים בירידה הזו בהילוך נמוך מתאים לסוג הרכב, לשיפוע ולאורך הירידה; ואם מותקנים ברכב מנגנונים להאטת מהירות בירידה – חובה להפעיל אותם בירידה הזו.', 'TR:159', 'הוצב בדרך תמרור המזהיר על ירידה מסוכנת', 'אלא בהילוך נמוך מתאים לפי סוג הרכב', 'על נוהג הרכב להפעילם שעה שהוא נוהג בירידה כאמור בתקנת משנה (ב)'),
