   R('בנסיעה מיוחדת נוסעים בדרך הקצרה ביותר האפשרית בנסיבות, ולא מעלים נוסע נוסף על המזמין ומלוויו – אלא אם המזמין ביקש.', 'TR:503', 'בדרך הקצרה ביותר האפשרית', also=[('TR:501', ['לא יסיע נהג המונית בנסיעה מיוחדת נוסע נוסף על מזמין הנסיעה'])]),
   R('בנמל התעופה בן־גוריון אסור לשדל נוסע לנסוע במונית – גם לא בקריאה או בסימן.', 'TR:517', 'לא ישדל אדם נוסע לנסוע במונית מהנמל', 'לרבות על ידי קריאה'),
