   R('רכב סיור: רכב ציבורי לעד שמונה נוסעים מלבד הנהג, שצוין ברישיונו כרכב סיור. נוהגים בו ברישיון D1 (ורישיון D כולל אותו).', 'TR:1', '”רכב סיור“ – רכב ציבורי המיועד להסיע עד שמונה נוסעים מלבד הנהג', also=[('TR:184', ['במונית, ברכב סיור ובאוטובוס זעיר'])]),
   R('"הסעת תלמידים" – הסעה בשכר של ילדים לבית ספר או לפעילות מאורגנת (למעט נסיעה בקו שירות); מבצעים אותה רק ברכב להסעת תלמידים או במונית עם רישיון לנסיעה מיוחדת.', 'TR:83(א)', 'לא יבצע אדם הסעת תלמידים, אלא ברכב להסעת תלמידים או במונית שניתן עליה רישיון לנסיעה מיוחדת', also=[('TR:1', ['”הסעת תלמידים“ – הסעה בשכר של ילדים לבית ספר', 'למעט בנסיעה בקו שירות'])]),
