# v1.5: lessons written for questions the whole-bank review found untaught (tools/lessons_v15.py)
def add_v15():
    from lessons_v15 import lessons
    for after, L in lessons(R, C):
        if any(x['id'] == L['id'] for x in LESSONS): continue
        i = next(i for i, x in enumerate(LESSONS) if x['id'] == after)
        LESSONS.insert(i + 1, L)
add_v15()

# v1.6: every B/A question taught from an official state source (tools/lessons_v16.py)
def add_v16():
    import lessons_v16 as m
    for after, L in m.lessons(R, C):
        assert not any(x['id'] == L['id'] for x in LESSONS), f"v1.6 lesson id {L['id']} already exists"  # never drop silently
        i = next(i for i, x in enumerate(LESSONS) if x['id'] == after)
        LESSONS.insert(i + 1, L)
    for k, v in m.EXAMPLES16.items(): EXAMPLES.setdefault(k, []).extend(X(*e) for e in v)
    for k, v in m.NOTES16.items(): NOTES.setdefault(k, v)
add_v16()

# v1.12: MoE traffic-education topics 7/13/17/21 + Compensation Law s.1, appended to existing lessons (tools/lessons_v112.py)
def add_v112():
    from lessons_v112 import extra
    for lid, rs in extra(R).items():
        L = next(x for x in LESSONS if x['id'] == lid)
        assert not any(r['t'] == x['t'] for r in rs for x in L['rules'])
        L['rules'].extend(rs)
add_v112()

